// TestUnit_Client_SendsPlainJSONBodies pins the wire shape of a write.
//
// Kiota's default middleware gzips every request body and sets
// Content-Encoding, and an API that does not read compressed bodies answers
// that with a bare 400 -- which is exactly how the first live acceptance run
// of the ThousandEyes pilot failed, with nothing in the error naming the
// cause. Recorded probe evidence is gathered over plain JSON, so plain JSON is
// the contract this client must keep; this test fails if the compression
// middleware ever comes back.
//
// The body is also compared field for field, because a pipeline that adds to
// what the caller sent is as wrong as one that encodes it differently.
func TestUnit_Client_SendsPlainJSONBodies(t *testing.T) {
	t.Parallel()

	type captured struct {
		method, path, contentType, encoding, auth string
		body                                      []byte
	}
	var got captured

	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		b, _ := io.ReadAll(r.Body)
		got = captured{
			method:      r.Method,
			path:        r.URL.String(),
			contentType: r.Header.Get("Content-Type"),
			encoding:    r.Header.Get("Content-Encoding"),
			auth:        r.Header.Get("Authorization"),
			body:        b,
		}
		w.WriteHeader(http.StatusNoContent)
	}))
	defer srv.Close()

	adapter := newTestAdapter(t, srv.URL+"/v1")

	info := probeRequest(t, abs.POST, srv.URL+"/v1/wire-probe")
	body := wireProbe{key: "tfacc-key", value: "tfacc-value"}
	if err := info.SetContentFromParsable(context.Background(), adapter, "application/json", body); err != nil {
		t.Fatalf("serializing the body: %v", err)
	}

	if err := adapter.SendNoContent(context.Background(), info, nil); err != nil {
		t.Fatalf("send: %v", err)
	}

	if got.method != http.MethodPost || got.path != "/v1/wire-probe" {
		t.Errorf("request = %s %s, want POST /v1/wire-probe", got.method, got.path)
	}
	if got.auth != "Bearer tok" {
		t.Errorf("Authorization = %q", got.auth)
	}
	if got.contentType != "application/json" {
		t.Errorf("Content-Type = %q", got.contentType)
	}
	if got.encoding != "" {
		t.Errorf("Content-Encoding = %q; the body must go uncompressed", got.encoding)
	}

	var decoded map[string]any
	if err := json.Unmarshal(got.body, &decoded); err != nil {
		t.Fatalf("the body is not plain JSON (%v):\n%q", err, got.body)
	}
	want := map[string]any{"key": "tfacc-key", "value": "tfacc-value"}
	if len(decoded) != len(want) {
		t.Errorf("the body carries %d fields, want %d: %s", len(decoded), len(want), got.body)
	}
	for field, wantVal := range want {
		if decoded[field] != wantVal {
			t.Errorf("body[%s] = %v, want %v (full body: %s)", field, decoded[field], wantVal, got.body)
		}
	}
}

// TestUnit_Client_DeleteAcceptsAJSONForm pins the Accept header of a delete.
//
// For an operation whose specification declares no success media type -- a
// DELETE whose only documented bodies are errors -- Kiota emits
// `Accept: application/problem+json` alone, and an API that takes that header
// at its word answers 406 Not Acceptable, which is how the ThousandEyes
// credential resource failed its first live acceptance run. The request below
// is built carrying exactly the header Kiota emits in that case; the client's
// acceptNormalizer must widen it to admit the API's real success forms before
// the request leaves. This test fails if a delete ever goes out refusing them
// again.
func TestUnit_Client_DeleteAcceptsAJSONForm(t *testing.T) {
	t.Parallel()

	var accept string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		accept = r.Header.Get("Accept")
		w.WriteHeader(http.StatusNoContent)
	}))
	defer srv.Close()

	adapter := newTestAdapter(t, srv.URL+"/v1")

	info := probeRequest(t, abs.DELETE, srv.URL+"/v1/wire-probe/11111111-1111-1111-1111-111111111111")
	info.Headers.TryAdd("Accept", "application/problem+json")

	if err := adapter.SendNoContent(context.Background(), info, nil); err != nil {
		t.Fatalf("send: %v", err)
	}

	if !strings.Contains(accept, "application/json") || !strings.Contains(accept, "application/hal+json") {
		t.Errorf("Accept = %q; a delete must admit the API's success media types or the server answers 406", accept)
	}
}

// TestUnit_Client_ModelConstructorsCarryNoDefaults pins that a freshly
// constructed request model holds nothing the caller did not set.
//
// Kiota constructors stamp every spec-declared default onto the model, and a
// defaulted field the provider never wires then leaks into every create -- which
// is how five ThousandEyes tests_* resources failed their first live acceptance
// run: the API refuses a Cloud Agent create carrying the spec-default
// networkMeasurements:true. The SDK is therefore generated from a document with
// its schema defaults stripped, and this test fails if a regeneration ever
// brings them back.
